import React, { useState, useEffect, useCallback, useRef } from 'react';
import styles from './fusion.module.scss';
import { useAppSelector } from '../../app/hooks';
import { selectUpgrades } from '../../app/gameSlice';
import { UPGRADES } from '../../Upgrades';

type Direction = 'up' | 'down' | 'left' | 'right' | 'up-left' | 'up-right' | 'down-left' | 'down-right';
type GameState = 'running' | 'crisis' | 'disabled';

interface CrisisCode {
  sequence: Direction[];
  currentIndex: number;
}

export const Fusion = () => {
  const upgrades = useAppSelector(selectUpgrades);

  const [gameState, setGameState] = useState<GameState>('crisis');
  const [multiplier, setMultiplier] = useState(1.1); // Начальный множитель
  const [runningMinutes, setRunningMinutes] = useState(0);
  const [crisisCount, setCrisisCount] = useState(0);
  const [currentBuilding, setCurrentBuilding] = useState<string>('hand');
  const [crisisCode, setCrisisCode] = useState<CrisisCode | null>({sequence: ['up', 'down', 'left', 'right'], currentIndex: 0});
  const [inputSequence, setInputSequence] = useState<Direction[]>([]);
  const [isSuccess, setIsSuccess] = useState(false);
  const [timeLeft, setTimeLeft] = useState(0);
  const [disabledUntil, setDisabledUntil] = useState<number | null>(null);
  
  const minuteTimerRef = useRef<NodeJS.Timeout | null>(null);
  const crisisTimerRef = useRef<NodeJS.Timeout | null>(null);
  const disabledTimerRef = useRef<NodeJS.Timeout | null>(null);
  const countdownRef = useRef<NodeJS.Timeout | null>(null);
  const upgradesRef = useRef(upgrades);

  // Инициализация currentBuilding и обновление ref при изменении upgrades
  useEffect(() => {
    upgradesRef.current = upgrades; // Обновляем ref
    const availableBuildings = upgrades.filter(u => u.level > 0);
    if (availableBuildings.length > 0 && currentBuilding === 'hand') {
      setCurrentBuilding(availableBuildings[0].id);
    }
  }, [upgrades, currentBuilding]);
    
  // Получаем список купленных апгрейдов (level > 0)
  const getAvailableBuildings = useCallback(() => {
    return upgrades
      .filter(upgrade => upgrade.level > 0)
      .map(upgrade => upgrade.id);
  }, [upgrades]);

  // Базовые вероятности кризисов по минутам (квадратичная функция)
  const getBaseCrisisProbability = useCallback((minute: number) => {
    if (minute < 1) return 0;
    // Квадратичная функция: y = 0.5x² + 3x, ограниченная 100%
    return Math.min(100, 0.5 * minute * minute + 3 * minute);
  }, []);

  // Вычисление текущей вероятности с учетом количества кризисов
  const getCurrentCrisisProbability = useCallback((minute: number, crisisCount: number) => {
    const baseProb = getBaseCrisisProbability(minute);
    return Math.min(100, baseProb * Math.pow(2, crisisCount));
  }, [getBaseCrisisProbability]);

  // Генерация кода для кризиса
  const generateCrisisCode = useCallback((minute: number, crisisCount: number) => {
    const codeLength = Math.max(3, Math.min(10, minute));
    const directions: Direction[] = ['up', 'down', 'left', 'right'];
    
    // На 4-й кризис добавляем невозможные символы
    if (crisisCount >= 3) {
      directions.push('up-left', 'up-right', 'down-left', 'down-right');
    }
    
    const sequence: Direction[] = [];
    for (let i = 0; i < codeLength; i++) {
      sequence.push(directions[Math.floor(Math.random() * directions.length)]);
    }
    
    return { sequence, currentIndex: 0 };
  }, []);

  // Смена здания каждую минуту - теперь без зависимостей
  const changeBuilding = useCallback(() => {
    const availableBuildings = upgradesRef.current.filter(upgrade => upgrade.level > 0).map(u => u.id);
    if (availableBuildings.length > 0) {
      const randomBuilding = availableBuildings[Math.floor(Math.random() * availableBuildings.length)];
      setCurrentBuilding(randomBuilding);
    }
  }, []); // Убираем зависимости, используем ref для актуальных upgrades

  // Проверка на кризис
  const checkForCrisis = useCallback(() => {
    if (gameState !== 'running') return;
    
    const probability = getCurrentCrisisProbability(runningMinutes, crisisCount);
    const roll = Math.random() * 100;
    
    if (roll < probability) {
      // Кризис!
      setGameState('crisis');
      const code = generateCrisisCode(runningMinutes, crisisCount);
      setCrisisCode(code);
      setInputSequence([]);
      setTimeLeft(30); // 30 секунд на ввод
      
      // Таймер обратного отсчета
      let countdown = 30;
      countdownRef.current = setInterval(() => {
        countdown--;
        setTimeLeft(countdown);
        if (countdown <= 0) {
          // Время вышло - неудача
          handleCrisisFailure();
        }
      }, 1000);
    }
  }, [gameState, runningMinutes, crisisCount, getCurrentCrisisProbability, generateCrisisCode]);

  // Обработка неудачи в кризисе
  const handleCrisisFailure = useCallback(() => {
    setGameState('disabled');
    setDisabledUntil(Date.now() + 60000); // 1 минута
    setCrisisCode(null);
    setInputSequence([]);
    
    // ПОЛНЫЙ СБРОС ИГРЫ К НАЧАЛЬНОМУ СОСТОЯНИЮ
    setCrisisCount(0); // Сброс счетчика кризисов
    setRunningMinutes(0); // Сброс времени работы
    setMultiplier(1.1); // Сброс множителя к начальному значению
    
    // Сброс здания к первому доступному
    const availableBuildings = getAvailableBuildings();
    if (availableBuildings.length > 0) {
      setCurrentBuilding(availableBuildings[0]);
    }
    
    if (countdownRef.current) {
      clearInterval(countdownRef.current);
      countdownRef.current = null;
    }
    
    // Таймер восстановления
    disabledTimerRef.current = setTimeout(() => {
      setGameState('running');
      setDisabledUntil(null);
    }, 60000);
  }, [getAvailableBuildings]);

  // Обработка успеха в кризисе
  const handleCrisisSuccess = useCallback(() => {
    setIsSuccess(true);
    setTimeout(() => {
      setGameState('running');
      setCrisisCount(prev => prev + 1);
      setCrisisCode(null);
      setInputSequence([]);
      setIsSuccess(false);
      
      if (countdownRef.current) {
        clearInterval(countdownRef.current);
        countdownRef.current = null;
      }
    }, 2000);
  }, []);

  // Обработка ввода направления
  const handleDirectionInput = useCallback((direction: Direction) => {
    if (gameState !== 'crisis' || !crisisCode) return;
    
    // Проверяем, можно ли ввести этот символ
    const impossibleDirections: Direction[] = ['up-left', 'up-right', 'down-left', 'down-right'];
    if (impossibleDirections.includes(direction)) {
      // Невозможный символ - сбрасываем ввод
      setInputSequence([]);
      return;
    }
    
    const newSequence = [...inputSequence, direction];
    setInputSequence(newSequence);
    
    // Проверяем правильность ввода
    const expectedDirection = crisisCode.sequence[newSequence.length - 1];
    if (direction !== expectedDirection) {
      // Неправильный ввод - сбрасываем
      setInputSequence([]);
      return;
    }
    
    // Проверяем, завершен ли код
    if (newSequence.length === crisisCode.sequence.length) {
      handleCrisisSuccess();
    }
  }, [gameState, crisisCode, inputSequence, handleCrisisSuccess]);

  // Обработка клавиатуры
  useEffect(() => {
    const handleKeyPress = (event: KeyboardEvent) => {
      if (gameState !== 'crisis') return;
      
      const keyMap: Record<string, Direction> = {
        'ArrowUp': 'up',
        'ArrowDown': 'down',
        'ArrowLeft': 'left',
        'ArrowRight': 'right',
        'KeyW': 'up',
        'KeyS': 'down',
        'KeyA': 'left',
        'KeyD': 'right',
        'KeyJ': 'left', 
        'KeyL': 'up', 
        'KeyK': 'down', 
        'Semicolon': 'right', 
      };
      
      const direction = keyMap[event.code] || keyMap[event.key];
      if (direction) {
        event.preventDefault();
        handleDirectionInput(direction);
      }
    };
    
    window.addEventListener('keydown', handleKeyPress);
    return () => window.removeEventListener('keydown', handleKeyPress);
  }, [gameState, handleDirectionInput]);

  // Основной игровой цикл - УБИРАЕМ changeBuilding из зависимостей
  useEffect(() => {
    if (gameState !== 'running') return;
    
    // Таймер минут
    minuteTimerRef.current = setInterval(() => {
      setRunningMinutes(prev => prev + 1);
              
      // Увеличиваем множитель
      setMultiplier(prevMult => prevMult + 0.1);
      
      // Меняем здание - используем стабильную ссылку
      changeBuilding();
    }, 60000); // Каждую минуту
    
    // Таймер проверки кризисов
    crisisTimerRef.current = setInterval(() => {
      console.log('checkForCrisis');
      checkForCrisis();
    }, 10000); // Проверяем каждые 10 секунд
    
    return () => {
      if (minuteTimerRef.current) clearInterval(minuteTimerRef.current);
      if (crisisTimerRef.current) clearInterval(crisisTimerRef.current);
    };
  }, [gameState, checkForCrisis]); // УБИРАЕМ changeBuilding из зависимостей

  // Очистка при размонтировании
  useEffect(() => {
    return () => {
      if (minuteTimerRef.current) clearInterval(minuteTimerRef.current);
      if (crisisTimerRef.current) clearInterval(crisisTimerRef.current);
      if (disabledTimerRef.current) clearTimeout(disabledTimerRef.current);
      if (countdownRef.current) clearInterval(countdownRef.current);
    };
  }, []);

  // Получение JSX элемента с иконкой направления
  const getDirectionIcon = (direction: Direction) => {
    const spriteClasses = {
      'up': `${styles.arrowSprite} ${styles.arrowUp}`,
      'down': `${styles.arrowSprite} ${styles.arrowDown}`,
      'left': `${styles.arrowSprite} ${styles.arrowLeft}`,
      'right': `${styles.arrowSprite} ${styles.arrowRight}`,
      'up-left': `${styles.arrowSprite} ${styles.arrowUpLeft}`,
      'up-right': `${styles.arrowSprite} ${styles.arrowUpRight}`,
      'down-left': `${styles.arrowSprite} ${styles.arrowDownLeft}`,
      'down-right': `${styles.arrowSprite} ${styles.arrowDownRight}`
    };
    return <span className={spriteClasses[direction]} />;
  };

  // Получение иконки здания из данных апгрейда
  const getBuildingIcon = (buildingId: string) => {
    const upgrade = UPGRADES.find(u => u.id === buildingId);
    return upgrade?.icon || '🏢';
  };
  
  // Получение названия здания из данных апгрейда
  const getBuildingName = (buildingId: string) => {
    const upgrade = UPGRADES.find(u => u.id === buildingId);
    return upgrade?.name || buildingId;
  };

  const animationSpeed = gameState === 'running' ? multiplier : 0;
  const disabledTimeLeft = disabledUntil ? Math.max(0, disabledUntil - Date.now()) : 0;

  return (
    <div className={styles.container}>
      <div className={styles.header}>
        <h3 className={styles.title}>Cold Fusion Generator</h3>
        <div className={styles.stats}>
          <span>Множитель: x{multiplier.toFixed(1)}</span>
          <span>Минут: {runningMinutes}</span>
          <span>Кризисов: {crisisCount}</span>
        </div>
      </div>

      <div className={styles.gameArea}>
        {/* Информация о текущем бонусе */}
        {getAvailableBuildings().length > 0 && (
          <div className={styles.bonusInfo}>
            <div className={styles.buildingIcon}>{getBuildingIcon(currentBuilding)}</div>
            <div className={styles.bonusText}>
              +{((multiplier - 1) * 100).toFixed(0)}% к {getBuildingName(currentBuilding)}
            </div>
          </div>
        )}
        {/* Основной реактор */}
        <div className={styles.reactorContainer}>
          {/* TODO: Добавить изображение железной стены со стеклом */}
          <div 
            className={`${styles.reactor} ${
              gameState === 'running' ? styles.running :
              gameState === 'disabled' ? styles.disabled :
              styles.crisis
            }`}
            style={{
              animationDuration: animationSpeed > 0 ? `${2 / animationSpeed}s` : 'infinite',
              animationPlayState: gameState === 'running' ? 'running' : 'paused'
            }}
          />
        </div>

        {/* Состояние отключения */}
        {gameState === 'disabled' && (
          <div className={styles.disabledOverlay}>
            <h4>Реактор отключен</h4>
            <p>Восстановление через: {Math.ceil(disabledTimeLeft / 1000)}с</p>
          </div>
        )}

        {/* Кризисная ситуация */}
        {gameState === 'crisis' && crisisCode && (
          <div className={styles.crisisOverlay}>
            <div className={styles.crisisPanel}>
              <h4>АВАРИЙНАЯ СИТУАЦИЯ!</h4>
              <p>Время: {timeLeft}с</p>

              <div className={styles.panel}>
                {/* D-Pad для ввода */}
              <div className={styles.dpad}>
                <div className={styles.dpadRow}>
                  <button 
                    className={styles.dpadBtn}
                    onClick={() => handleDirectionInput('up')}
                  >
                    <span className={`${styles.arrowSprite} ${styles.arrowUp}`} />
                  </button>
                </div>
                <div className={styles.dpadRow}>
                  <button 
                    className={styles.dpadBtn}
                    onClick={() => handleDirectionInput('left')}
                  >
                    <span className={`${styles.arrowSprite} ${styles.arrowLeft}`} />
                  </button>
                  <div className={styles.dpadCenter}></div>
                  <button 
                    className={styles.dpadBtn}
                    onClick={() => handleDirectionInput('right')}
                  >
                    <span className={`${styles.arrowSprite} ${styles.arrowRight}`} />
                  </button>
                </div>
                <div className={styles.dpadRow}>
                  <button 
                    className={styles.dpadBtn}
                    onClick={() => handleDirectionInput('down')}
                  >
                    <span className={`${styles.arrowSprite} ${styles.arrowDown}`} />
                  </button>
                </div>
              </div>
              
              {/* Код для ввода */}
              <div>
                <div className={styles.codeDisplay}>
                  {crisisCode.sequence.map((direction, index) => (
                    <span 
                      key={index}
                      className={`${styles.codeSymbol} ${
                        index < inputSequence.length ? styles.entered :
                        index === inputSequence.length ? styles.current :
                        styles.pending
                      }`}
                    >
                      {getDirectionIcon(direction)}
                    </span>
                  ))}
                </div>
                
                {/* Введенная последовательность */}
                <div className={styles.inputDisplay}>
                  Введено: {inputSequence.map((dir, index) => (
                    <React.Fragment key={index}>
                      {getDirectionIcon(dir)}
                      {index < inputSequence.length - 1 && ' '}
                    </React.Fragment>
                  ))}
                </div>
              </div>

              </div>

              
            </div>
          </div>
        )}

        {/* Сообщение об успехе */}
        {isSuccess && (
          <div className={styles.successOverlay}>
            <h4>КРИЗИС ПРЕДОТВРАЩЕН!</h4>
            <p>Реактор продолжает работу</p>
          </div>
        )}
      </div>
    </div>
  );
}; 