import React, { useState, useEffect, useRef, useCallback } from 'react';
import {
  ComposableMap,
  Geographies,
  Geography,
  ZoomableGroup,
} from 'react-simple-maps';
import { feature } from 'topojson-client';
import { geoPath, geoNaturalEarth1 } from 'd3-geo';
import countriesData from '../../assets/pre/countries-110m.json';
import { useAppDispatch, useAppSelector } from '../../app/hooks';
import { 
  selectCountry, 
  manualClick, 
  selectedCountry, 
  selectConqueredCountries, 
  selectManualClickPower,
  selectStage,
  selectShowMinistryPopup,
  selectTalentBeacons,
  collectTalent,
  selectFlags,
  placeFlagOnCountry,
  selectMapEvents,
  selectTotal,
  selectCommonMultiplier,
  selectFlagsActive
} from '../../app/gameSlice';
import { showCoinEffectThunk } from '../../app/visualEffectsSlice';
import { CoinEffects } from '../../components/CoinEffects';
import { MinistryPopup } from '../../components/MinistryPopup/MinistryPopup';
import { QuestSystem } from '../../components/QuestSystem/QuestSystem';
import { ParticleEffects, ParticleEffectsRef } from '../../components/ParticleEffects';
import { Feature } from 'geojson';
import styles from './WorldMap.module.css';
import { GameEvents } from '../../components/GameEvents';
import { Flag } from '../../types';
import { COUNTRIES } from '../../Countries';
import { Marker } from './map/marker/marker';
import { LaunchPad } from '../../components/LaunchPad';
import { COLORS } from '../../constants';

interface Country {
  id: string;
  name: string;
  centroid: [number, number];
  color: 'default' | 'red' | 'yellow';
}



export const WorldMap: React.FC<{onCountryClick: (pos: { x: number; y: number }, countryId: string) => void}> = ({onCountryClick}) => {
  const dispatch = useAppDispatch();
  
  // Redux состояние
  const gameSelectedCountry = useAppSelector(selectedCountry);
  const conqueredCountries = useAppSelector(selectConqueredCountries);
  const manualClickPower = useAppSelector(selectManualClickPower);
  const stage = useAppSelector(selectStage);
  const showMinistryPopup = useAppSelector(selectShowMinistryPopup);
  const talentBeacons = useAppSelector(selectTalentBeacons);
  const flags = useAppSelector(selectFlags);
  const events = useAppSelector(selectMapEvents);
  const total = useAppSelector(selectTotal);
  const commonMultiplier = useAppSelector(selectCommonMultiplier)
  const flagsActive = useAppSelector(selectFlagsActive);
  
  // Локальное состояние для карты
  const [countries, setCountries] = useState<Country[]>([]);
  const [draggedFlag, setDraggedFlag] = useState<string | null>(null);
  const [animatingCountries, setAnimatingCountries] = useState<Set<string>>(new Set());
  const [mapDimensions, setMapDimensions] = useState({ width: 800, height: 600 });
  const mapRef = useRef<SVGSVGElement>(null);
  const particleEffectsRef = useRef<ParticleEffectsRef>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  
  // Состояние для подсказки флагов
  const [flagsFirstAppeared, setFlagsFirstAppeared] = useState<number>(0);
  const [lastHoverTime, setLastHoverTime] = useState<number>(0);
  const [showFlagHint, setShowFlagHint] = useState<boolean>(false);
  const [hasPlacedAnyFlag, setHasPlacedAnyFlag] = useState<boolean>(false);
  
  // Отслеживание размеров контейнера
  useEffect(() => {
    const updateDimensions = () => {
      if (containerRef.current) {
        const rect = containerRef.current.getBoundingClientRect();
        setMapDimensions({ width: rect.width, height: rect.height });
      }
    };

    updateDimensions();
    
    // Добавляем passive слушатель для resize события
    window.addEventListener('resize', updateDimensions, { passive: true });
    
    // Также отслеживаем изменения размера с помощью ResizeObserver
    const resizeObserver = new ResizeObserver(updateDimensions);
    if (containerRef.current) {
      resizeObserver.observe(containerRef.current);
    }

    return () => {
      window.removeEventListener('resize', updateDimensions);
      resizeObserver.disconnect();
    };
  }, []);

  // Инициализация стран из TopoJSON данных с правильной проекцией
  useEffect(() => {
    if (mapDimensions.width === 0 || mapDimensions.height === 0) return;
    
    const topology = countriesData as any;
    const geographies = feature(topology, topology.objects.countries) as any;
    
    // Используем динамические размеры карты для проекции
    const projection = geoNaturalEarth1()
      .scale(Math.min(mapDimensions.width, mapDimensions.height) * 0.2)
      .translate([mapDimensions.width / 2, mapDimensions.height / 2]);
    const path = geoPath().projection(projection);
    
    const countryList: Country[] = geographies.features.map((geo: any) => {
      const centroid = path.centroid(geo);
      return {
        id: geo.properties.name, // Используем имя страны как ID для совместимости
        name: geo.properties.name,
        centroid: centroid as [number, number],
        color: 'default' as const,
      };
    });
    
    setCountries(countryList);
  }, [mapDimensions]);

  const beacons = talentBeacons.map(b => {
    const centroid = countries.find(country=> country.id === b.countryId)?.centroid || [b.x, b.y];
    return {
      ...b,
      x: centroid[0],
      y: centroid[1]
    }
  });

  const handleCountryClick = useCallback((geo: Feature, event: React.MouseEvent) => {
    
    const countryId = geo.properties?.name as string;
    // Если страна еще не выбрана - выбираем первую страну
    if (!gameSelectedCountry) {
      dispatch(selectCountry(geo.properties?.name || ''));
      setCountries(prev => 
        prev.map(c => c.id === countryId ? { ...c, color: 'red' } : c)
      );
      return;
    }
    
    // Проверяем, что это выбранная страна или захваченная
    const isClickableCountry = countryId === gameSelectedCountry || conqueredCountries.includes(countryId);
    
    if (isClickableCountry) {
      onCountryClick({ x: event.clientX, y: event.clientY}, countryId);      
      // Анимация подпрыгивания страны
      setAnimatingCountries(prev => new Set(Array.from(prev).concat(countryId)));
      setTimeout(() => {
        setAnimatingCountries(prev => {
          const newSet = new Set(prev);
          newSet.delete(countryId);
          return newSet;
        });
      }, 300);
    }
  }, [dispatch, gameSelectedCountry, conqueredCountries, manualClickPower, countries]);
  
  const handleFlagDragStart = (flagId: string, event: React.DragEvent) => {
    setDraggedFlag(flagId);
    event.dataTransfer.setData('text/plain', flagId);
  };
  
  const handleFlagDrop = (countryName: string, event: React.DragEvent) => {
    if (draggedFlag) {
      event.preventDefault(); // Только предотвращаем если есть перетаскиваемый флаг
      const country = countries.find(c => c.name === countryName);
      if (country) {
        // Размещаем флаг на стране через Redux
        dispatch(placeFlagOnCountry({
          flagId: draggedFlag,
          countryId: countryName,
          x: country.centroid[0],
          y: country.centroid[1]
        }));
        
        // Окрашиваем страну в желтый (захват начался)
        setCountries(prev => 
          prev.map(c => c.name === countryName ? { ...c, color: 'yellow' } : c)
        );
        
        // Отмечаем что флаг установлен - убираем подсказки навсегда
        setHasPlacedAnyFlag(true);
        setShowFlagHint(false);
      }
      setDraggedFlag(null);
    }
  };
  
  const handleTalentBeaconClick = (beaconId: string) => {
    dispatch(collectTalent(beaconId));
  };
  
  const getCountryColor = useCallback((countryId: string): string => {
    // Проверяем, является ли это выбранной страной
    if (countryId === gameSelectedCountry) {
      return COLORS.Cinnabar; // красный для выбранной страны
    }
    
    // Проверяем, является ли это захваченной страной
    if (conqueredCountries.includes(countryId)) {
      return COLORS["Cornell red"]; // желтый для захваченных стран
    }
    
    // Обычный цвет для остальных стран
    return '#e0e0e0';
  }, [gameSelectedCountry, conqueredCountries]);

  const handleFilter = (event: any) => {
    // Фильтруем события двойного клика для ZoomableGroup
    return event.type !== "dblclick";
  };

  // Обработчик для предотвращения drag over только когда нужно
  // Это помогает избежать предупреждений о non-passive event listeners
  const handleDragOver = useCallback((event: React.DragEvent) => {
    if (draggedFlag) {
      event.preventDefault(); // Только если есть перетаскиваемый флаг
    }
  }, [draggedFlag]);

  // Обработчик двойного клика с условным preventDefault
  // Предотвращает случайное масштабирование карты при двойном клике
  const handleDoubleClick = useCallback((event: React.MouseEvent) => {
    event.preventDefault();
  }, []);

  // Эффект для показа autoPower над захваченными странами
  useEffect(() => {    
    const interval = setInterval(() => {
      conqueredCountries.forEach((countryName) => {
        const country = countries.find(c => c.name === countryName || c.id === countryName);
        const countryData = COUNTRIES[countryName];
        
        if (country && countryData && countryData?.autoPower * commonMultiplier > 1) {
          // Получаем глобальные координаты для эффекта
          if (containerRef.current) {
            const containerRect = containerRef.current.getBoundingClientRect();
            const globalPos = {
              x: containerRect.left + country.centroid[0],
              y: containerRect.top + country.centroid[1]
            };
            
            // Добавляем случайную задержку для каждой страны (0-500мс)
            setTimeout(() => {
              dispatch(showCoinEffectThunk({
                position: globalPos,
                value: countryData.autoPower * commonMultiplier,
                prefix: '+',
                suffix: '₿', 
              }));
            }, Math.random() * 500);
          }
        }
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [conqueredCountries, countries, commonMultiplier, dispatch]);

  // Отслеживание первого появления флагов
  useEffect(() => {
    if (flags.length > 0 && flagsFirstAppeared === 0 && !hasPlacedAnyFlag) {
      setFlagsFirstAppeared(Date.now());
    }
  }, [flags.length, flagsFirstAppeared, hasPlacedAnyFlag]);

  // Таймер для показа подсказки
  useEffect(() => {
    if (hasPlacedAnyFlag || flagsFirstAppeared === 0) {
      return;
    }

    const interval = setInterval(() => {
      const now = Date.now();
      const timeSinceFlags = now - flagsFirstAppeared;
      const timeSinceHover = now - lastHoverTime;
      
      // Показать подсказку если прошло 30сек с появления флагов или с последнего hover
      const shouldShowHint = (timeSinceFlags >= 30000) && 
                            (lastHoverTime === 0 || timeSinceHover >= 30000);
      
      if (shouldShowHint && !showFlagHint) {
        setShowFlagHint(true);
      }
    }, 5000); // Проверяем каждые 5 секунд

    return () => clearInterval(interval);
  }, [flagsFirstAppeared, lastHoverTime, hasPlacedAnyFlag, showFlagHint]);

  // Обработчики hover для полочки
  const handleFlagShelfHover = () => {
    if (!hasPlacedAnyFlag) {
      setLastHoverTime(Date.now());
      setShowFlagHint(false);
    }
  };
  
  return (
    <div ref={containerRef} className={styles.worldMapContainer}>
    {/* Эффекты частиц */}
    <ParticleEffects ref={particleEffectsRef} />
    
    {/* Полочка с флагами */}
    {flagsActive && !!flags.length && (
      <div 
        className={styles.flagShelf}
        onMouseEnter={handleFlagShelfHover}
      >
      {flags.filter(f => !f.countryId).map(flag => (
        <div
        key={flag.id}
        draggable
        onDragStart={(e) => handleFlagDragStart(flag.id, e)}
        className={styles.flag}
        >
          {/* Флаг - палка с прямоугольником */}
          <svg width="30" height="40">
            <line x1="2" y1="0" x2="2" y2="40" stroke="#8B4513" strokeWidth="2" />
            <rect x="4" y="2" width="22" height="15" fill="#ff6b6b" stroke="#333" strokeWidth="1" />
          </svg>
        </div>
      ))}
      </div>
    )}

    {/* Стрелка-подсказка для флагов */}
    {showFlagHint && !hasPlacedAnyFlag && flagsActive && (() => {
      // Определяем целевую страну
      const targetCountry = gameSelectedCountry === 'United States of America' ? 'Russia' : 'United States of America';
      
      // Находим координаты центра целевой страны
      const targetCountryData = countries.find(c => c.name === targetCountry);
      if (!targetCountryData) return null;
      
      const targetX = targetCountryData.centroid[0];
      const targetY = targetCountryData.centroid[1];
      
      // Вычисляем координаты самого правого флага
      const availableFlags = flags.filter(f => !f.countryId);
      const flagShelfLeft = 20; // позиция полочки слева
      const flagShelfTop = 20; // позиция полочки сверху  
      const flagWidth = 30; // ширина одного флага
      const flagGap = 10; // расстояние между флагами
      
      // Координаты самого правого флага
      const rightmostFlagIndex = availableFlags.length - 1;
      const startX = flagShelfLeft + 10 + (rightmostFlagIndex * (flagWidth + flagGap)) + flagWidth / 2; // центр последнего флага
      const startY = flagShelfTop + 10 + 40; // нижняя точка флага (padding 10px + высота флага 40px)
      
      // Вычисляем контрольную точку для кривой (примерно посередине)
      const controlX = (startX + targetX) / 2;
      const controlY = (startY + targetY) / 2 - 50; // Немного выше для красивой дуги
      
      // Позиция текста примерно на середине стрелки
      const textX = (startX + targetX) / 2;
      const textY = (startY + targetY) / 2;
      
      return (
        <div 
          className={styles.flagHintArrow}
          onMouseEnter={handleFlagShelfHover}
        >
          <svg 
            width={mapDimensions.width} 
            height={mapDimensions.height} 
            style={{ position: 'absolute', top: '0px', left: '0px', pointerEvents: 'none' }}
          >
            <defs>
              <marker id="arrowhead" markerWidth="10" markerHeight="7" 
                      refX="9" refY="3.5" orient="auto">
                <polygon points="0 0, 10 3.5, 0 7" fill="#ffd700" />
              </marker>
            </defs>
            <path 
              d={`M ${startX} ${startY} Q ${controlX} ${controlY} ${targetX} ${targetY}`}
              stroke="#ffd700" 
              strokeWidth="3" 
              fill="none" 
              markerEnd="url(#arrowhead)"
            />
            <text x={textX} y={textY} fill="#000000" fontSize="18" fontWeight="bold" textAnchor="middle">+₿</text>
          </svg>
        </div>
      );
    })()}
    
    {/* Карта мира */}
    <ComposableMap
    ref={mapRef}
    projection="geoNaturalEarth1"
    projectionConfig={{
      scale: Math.min(mapDimensions.width, mapDimensions.height) * 0.2,
      center: [0, 0],
    }}
    width={mapDimensions.width}
    height={mapDimensions.height}
    className={styles.map}
    onDoubleClick={handleDoubleClick}
    >
    <ZoomableGroup
      {...({ filterZoomEvent: handleFilter } as any)}
    >
      <Geographies geography={countriesData}>
        {({ geographies }: { geographies: any[] }) =>
          geographies.map((geo: any) => (
          <Geography
            key={geo.PsmKey}
            geography={geo}
            {...({ onClick: (event: React.MouseEvent) => handleCountryClick(geo, event) } as any)}
            onDoubleClick={handleDoubleClick}
            onDrop={(event: React.DragEvent) => handleFlagDrop(geo.properties?.name || '', event)}
            onDragOver={handleDragOver}
            fill={getCountryColor(geo.properties?.name || '')}
            stroke="#fff"
            strokeWidth={0.5}
            className={animatingCountries.has(geo.id) ? styles.countryAnimated : styles.countryDefault}
            style={{
              default: {
                outline: 'none',
                cursor: (geo.properties?.name === gameSelectedCountry || conqueredCountries.includes(geo.properties?.name)) ? 'pointer' : 'default',
              },
              hover: {
                outline: 'none',
                fill: (!!gameSelectedCountry ?
                  geo.properties?.name === gameSelectedCountry || conqueredCountries.includes(geo.properties?.name) ? COLORS.Melon : getCountryColor(geo.properties?.name || '')
                  : '#ccc'),
                cursor: !!gameSelectedCountry ? ((geo.properties?.name === gameSelectedCountry || conqueredCountries.includes(geo.properties?.name)) ? 'pointer' : 'default') : 'pointer',
              },
              pressed: {
                outline: 'none',
                transform: 'scale(0.95)',
              },
            }}
          />
        ))
      }
      </Geographies
      >
      {/* Стартовая площадка с ракетой над выбранной страной */}
      {gameSelectedCountry && (
        (() => {
          const selectedCountryData = countries.find(c => c.name === gameSelectedCountry);
          if (selectedCountryData) {
            return (
              <LaunchPad
                x={selectedCountryData.centroid[0]}
                y={selectedCountryData.centroid[1]}
              />
            );
          }
          return null;
        })()
      )}
      
      {/* Размещенные флаги */}
      {flags.filter(f => f.countryId).map(flag => (
        <g key={flag.id}>
          <line x1={flag.x} y1={flag.y} x2={flag.x} y2={flag.y + 25} stroke="#8B4513" strokeWidth="2" />
          <rect x={flag.x + 2} y={flag.y} width="15" height="10" fill="#ff6b6b" stroke="#333" strokeWidth="1" />
        </g>
      ))}
      
      {/* Пуансоны талантов */}
      {beacons.map(beacon => (
          <Marker key={beacon.id} beacon={beacon} handleTalentBeaconClick={handleTalentBeaconClick} />  
      ))}

      

    </ZoomableGroup>
    </ComposableMap>
    
    {/* Эффекты монет */}
    <CoinEffects />
    
    {/* Попап министерства финансов */}
    {showMinistryPopup && <MinistryPopup />}
    
    {/* Система квестов */}
    {stage > 0 && <QuestSystem />}

    {/* Компонент для отображения игровых событий */}
    <GameEvents />
  </div>
);
};
