import React, { useState, createContext, useContext } from 'react';
import styles from './index.module.scss';
import { resetGame, updateResources, updateGameState, updateFTLEnergy } from '../../app/gameSlice';
import { useAppDispatch, useAppSelector } from '../../app/hooks';
import { COMMON } from '../../app/constants';
import { GAME_EVENTS } from '../../Events';
import { COUNTRY_NAMES } from '../../constants';

// Функция для генерации случайной позиции
const getRandomPosition = (windowSize: { width: number, height: number } = { width: 1200, height: 800 }): [number, number] => {
  const margin = 50;
  const x = margin + Math.random() * (windowSize.width - margin * 2);
  const y = margin + Math.random() * (windowSize.height - margin * 2);
  return [x, y];
};

// Контекст для DevTools состояния
interface DevToolsContextType {
  showAllTalents: boolean;
  setShowAllTalents: (show: boolean) => void;
}

const DevToolsContext = createContext<DevToolsContextType | undefined>(undefined);

export { DevToolsContext };

export const useDevTools = () => {
  const context = useContext(DevToolsContext);
  if (!context) {
    return { showAllTalents: false, setShowAllTalents: () => {} };
  }
  return context;
};

export const DevToolsProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [showAllTalents, setShowAllTalents] = useState(false);
  
  return (
    <DevToolsContext.Provider value={{ showAllTalents, setShowAllTalents }}>
      {children}
    </DevToolsContext.Provider>
  );
};

export const DevTools = () => {
  const dispatch = useAppDispatch();
  const [isExpanded, setIsExpanded] = useState(false);
  const { showAllTalents, setShowAllTalents } = useDevTools();
  const currentTalentPoints = useAppSelector(state => state.game.talentPoints);
  const currentTotal = useAppSelector(state => state.game.total);
  const activeProjects = useAppSelector(state => state.game.activeProjects);
  const currentActiveEvents = useAppSelector(state => state.game.activeEvents);
  const currentEventHistory = useAppSelector(state => state.game.eventHistory);
  
  const handleAddResources = () => {
    dispatch(updateResources({
      resources: { [COMMON]: 1e7 }
    }));
  };
  const handleAddCosmicResources = () => {
    dispatch(updateResources({
      resources: { [COMMON]: Number.MAX_VALUE * 0.05 }
    }));
  };
  const handleAddFTLResources = () => {
    dispatch(updateFTLEnergy(Number.MAX_VALUE * 0.05));
  };


  const handleAddTalentPoint = () => {
    dispatch(updateGameState({
      talentPoints: currentTalentPoints + 1
    }));
  };
  const handleAddTalentsPoint = () => {
    dispatch(updateGameState({
      talentPoints: currentTalentPoints + 60
    }));
  };

  const handleShowAllUI = () => {
    // Устанавливаем total >= 100 для showShop и showTalents
    const newTotal = Math.max(currentTotal, 100);
    
    // Добавляем проект если его еще нет
    const newActiveProjects = activeProjects.length === 0 ? [
      {
        id: 'dysonSphere',
        status: 'in_progress' as const,
        progress: 0
      }
    ] : activeProjects;

    dispatch(updateGameState({
      total: newTotal,
      activeProjects: newActiveProjects
    }));
  };

  const handleTestFlags = () => {
    // Активируем флаги и добавляем несколько для тестирования
    dispatch(updateGameState({
      flagsActive: true,
      flags: [
        { id: 'flag1', countryId: undefined, x: 0, y: 0 },
        { id: 'flag2', countryId: undefined, x: 0, y: 0 }
      ]
    }));
  };

  const handleShowAllTalents = () => {
    setShowAllTalents(!showAllTalents);
  };

  const handleCreateRandomEvent = () => {
    // Получаем все доступные события
    const eventKeys = Object.keys(GAME_EVENTS);
    if (eventKeys.length === 0) return;
    
    // Выбираем случайное событие
    const randomEventKey = eventKeys[Math.floor(Math.random() * eventKeys.length)];
    const randomEvent = GAME_EVENTS[randomEventKey];
    
    // Создаем случайную позицию
    const position = getRandomPosition();
    
    // Проверяем, что событие еще не активно
    const isAlreadyActive = currentActiveEvents.some(e => e.id === randomEventKey);
    if (isAlreadyActive) {
      console.log(`Событие ${randomEvent.name} уже активно`);
      return;
    }
    
    // Добавляем новое событие к активным событиям
    const newActiveEvents = [
      ...currentActiveEvents,
      {
        id: randomEventKey,
        position
      }
    ];
    
    // Обновляем состояние игры
    dispatch(updateGameState({
      activeEvents: newActiveEvents,
      eventHistory: {
        ...currentEventHistory,
        [randomEventKey]: {
          id: randomEventKey,
          lastTriggered: Date.now(),
          count: (currentEventHistory[randomEventKey]?.count || 0) + 1
        }
      }
    }));
    
    console.log(`Создано случайное событие: ${randomEvent.name}`);
  };

  const handleTestStageTwo = () => {
    // Берем первые 150 стран из списка COUNTRY_NAMES для захвата
    const countriesToConquer = COUNTRY_NAMES.slice(0, 150);
    
    // Обновляем состояние игры
    dispatch(updateGameState({
      conqueredCountries: countriesToConquer,
      stage: 1, // Оставляем на первом этапе, логика перехода сработает автоматически
      total: Math.max(currentTotal, 100000), // Даем достаточно ресурсов
      resources: Math.max(currentTotal, 100000),
    }));
    
    console.log(`Добавлено ${countriesToConquer.length} стран для перехода ко второму этапу`);
  };

  const handleToggleExpanded = () => {
    setIsExpanded(!isExpanded);
  };
  
  return (
    <>
      <div className={styles.devTools}>
        <button 
          onClick={handleToggleExpanded}
          className={`${styles.toggleButton} ${isExpanded ? styles.active : ''}`}
        >
          {isExpanded ? '−' : '+'}
        </button>
        
        {isExpanded && (
          <div className={styles.devToolsContent}>
            <button onClick={() => dispatch(resetGame())}>Сбросить игру</button>
            <button onClick={handleAddResources}>+10000 ресурсов</button>
            <button onClick={handleAddCosmicResources}>+5% ресурсов</button>
            <button onClick={handleAddFTLResources}>+5% FTL энергии</button>
            <button onClick={handleAddTalentPoint}>+1 очко талантов</button>
            <button onClick={handleAddTalentsPoint}>+60 очков талантов</button>
            <button onClick={handleShowAllUI}>Показать все UI элементы</button>
            <button onClick={handleTestFlags}>Активировать флаги</button>
            <button 
              onClick={handleShowAllTalents}
              className={showAllTalents ? styles.active : ''}
            >
              {showAllTalents ? 'Скрыть' : 'Показать все'} таланты
            </button>
            <button onClick={handleCreateRandomEvent}>Создать случайное событие</button>
            <button onClick={handleTestStageTwo}>
              Захватить 150 стран (2 этап)
            </button>
          </div>
        )}
      </div>
    </>
  );
};
