import React from 'react';
import { COLLIDER_GAME, PSI_GAME, WORMHOLE, FUSION, DYSON_SPHERE } from '../../constants';
import { Collider } from '../../projects/collider';
import { Psi } from '../../projects/psi';
import { Wormhole } from '../../projects/wormhole';
import { Fusion } from '../../projects/fusion';
import { DysonSphere } from '../../projects/dyson-sphere';

export const Games = ({ gameId }: { gameId: string }) => {
  switch (gameId) {
    case COLLIDER_GAME:
      return <Collider />;
    case PSI_GAME:
      return <Psi />;
    case WORMHOLE:
      return <Wormhole />;
    case FUSION:
      return <Fusion />;
    case DYSON_SPHERE:
      return <DysonSphere />;
    default:
      return null;
  }
};