import React, { useEffect, useRef } from 'react';
import styles from './index.module.scss';

interface ParticleProps {
    x: number;
    y: number;
    size: number;
    speed: number;
    distance: number;
    angle: number;
    acceleration: number;
    opacity: number;
    maxOpacity: number;
    spawnTime: number;
}

const FTLjump: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;

        // Настройки частиц
        const particles: Particle[] = [];
        const settings = {
            quantity: 500,         // Кол-во "звёзд"
            initialSpeed: 0.5,     // Начальная скорость
            maxSpeed: 15,          // Максимальная скорость
            acceleration: 0.3,     // Ускорение
            lineLength: 0.15,      // Длина линии (доля от экрана)
            opacity: 0.9,          // Максимальная прозрачность
            fadeDistance: 0.05,    // Расстояние для появления (5% от ширины экрана)
            groupSpawnChance: 0.3, // Шанс группового спавна (30%)
            groupSize: 10        
        };

        let lastGroupSpawn = 0;
        let animationTime = 0;

        // Инициализация частиц
        class Particle implements ParticleProps {
            x: number;
            y: number;
            size: number;
            speed: number;
            distance: number;
            angle: number;
            acceleration: number;
            opacity: number;
            maxOpacity: number;
            spawnTime: number;

            constructor(spawnTime: number = 0) {
                this.x = 0;
                this.y = 0;
                this.size = 0;
                this.speed = settings.initialSpeed;
                this.distance = 0;
                this.angle = Math.random() * Math.PI * 2;
                this.acceleration = settings.acceleration;
                this.opacity = 0;
                this.maxOpacity = Math.random() * settings.opacity + 0.3;
                this.spawnTime = spawnTime;
                this.reset();
            }
            
            reset() {
                this.x = canvas!.width / 2;
                this.y = canvas!.height / 2;
                this.size = Math.random() * 2 + 0.5;
                this.speed = settings.initialSpeed;
                this.distance = 0;
                this.opacity = 0;
            }

            update() {
                // Ускорение частицы
                if (this.speed < settings.maxSpeed) {
                    this.speed += this.acceleration;
                }

                // Движение от центра
                this.x += Math.cos(this.angle) * this.speed;
                this.y += Math.sin(this.angle) * this.speed;
                this.distance += this.speed;

                // Плавное появление прозрачности
                const fadeThreshold = canvas!.width * settings.fadeDistance;
                if (this.distance < fadeThreshold) {
                    this.opacity = (this.distance / fadeThreshold) * this.maxOpacity;
                } else {
                    this.opacity = this.maxOpacity;
                }
                
                // Сброс при выходе за границы
                if (this.distance > canvas!.width) {
                    this.reset();
                }
            }

            draw() {
                if (this.opacity <= 0) return;

                // Рисуем линию (точка + хвост)
                // Длина хвоста зависит от скорости
                const tailLength = Math.min(this.speed * 4, 40);
                const tailX = this.x - Math.cos(this.angle) * tailLength;
                const tailY = this.y - Math.sin(this.angle) * tailLength;
                
                // Создаем градиент для плавного хвоста
                const gradient = ctx!.createLinearGradient(tailX, tailY, this.x, this.y);
                gradient.addColorStop(0, `rgba(255, 255, 255, 0)`);
                gradient.addColorStop(1, `rgba(255, 255, 255, ${this.opacity})`);
                
                ctx!.beginPath();
                ctx!.lineWidth = this.size;
                ctx!.strokeStyle = gradient;
                ctx!.moveTo(tailX, tailY);
                ctx!.lineTo(this.x, this.y);
                ctx!.stroke();

                // Рисуем яркую точку в конце
                ctx!.beginPath();
                ctx!.fillStyle = `rgba(255, 255, 255, ${this.opacity})`;
                ctx!.arc(this.x, this.y, this.size * 0.8, 0, Math.PI * 2);
                ctx!.fill();
            }
        }

        // Создание частиц
        function initParticles() {
            for (let i = 0; i < settings.quantity; i++) {
                particles.push(new Particle());
            }
        }

        // Групповой спавн частиц
        function spawnGroup() {
            for (let i = 0; i < settings.groupSize; i++) {
                if (particles.length < settings.quantity * 3) { // Ограничиваем общее количество
                    particles.push(new Particle(animationTime));
                }
            }
        }

        // Случайный спавн одиночных частиц
        function spawnRandomParticles() {
            // Спавним 1-3 частицы случайно каждый кадр
            const spawnCount = Math.random() < 0.8 ? Math.floor(Math.random() * 3) + 1 : 0;
            for (let i = 0; i < spawnCount; i++) {
                if (particles.length < settings.quantity * 2) {
                    particles.push(new Particle(animationTime));
                }
            }
        }

        // Анимация
        function animate() {
            animationTime += 0.016;
            
            // Очищаем canvas полностью для прозрачного фона
            ctx!.clearRect(0, 0, canvas!.width, canvas!.height);

            // Постоянный случайный спавн частиц
            spawnRandomParticles();

            // Редкий групповой спавн
            if (Math.random() < 0.005 && // 0.5% шанс каждый кадр
                animationTime - lastGroupSpawn > 2) { // Минимум 2 секунды между группами
                spawnGroup();
                lastGroupSpawn = animationTime;
            }

            // Обновляем и рисуем частицы
            for (let i = particles.length - 1; i >= 0; i--) {
                const particle = particles[i];
                particle.update();
                particle.draw();

                // Удаляем частицы, которые вышли за пределы экрана
                if (particle.distance > canvas!.width * 0.8) {
                    particles.splice(i, 1);
                }
            }

            requestAnimationFrame(animate);
        }

        initParticles();
        animate();

        // Ресайз для адаптивности
        const handleResize = () => {
            canvas!.width = window.innerWidth;
            canvas!.height = window.innerHeight;
        };

        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
        };
    }, []);

    return (
        <canvas className={styles.ftlCanvas} ref={canvasRef}></canvas>
    );
};

export default FTLjump;