import { Middleware, MiddlewareAPI, Dispatch, UnknownAction } from 'redux';
import { RootState } from './store';

// Создаем единый экземпляр воркера для всего приложения
export const gameWorker = new Worker(new URL('./gameLoop/gameLoop.ts', import.meta.url));

// Локальное состояние для middleware
let isStartScreenVisible = true;

// Middleware для работы с воркером
export const workerMiddleware: Middleware = 
  (store: MiddlewareAPI) => {
  
  // Подписываемся на сообщения от воркера
  gameWorker.onmessage = (e) => {
    const { game, sound } = e.data;
    // Обновляем состояние игры при получении данных от воркера
    store.dispatch({ type: 'game/updateGameState', payload: game });
    // Обновляем звуковое состояние если есть изменения
    if (sound && Object.keys(sound).length > 0) {
      // Если есть запрос на воспроизведение музыки, обрабатываем его
      if (sound.playMusicRequest) {
        const { key, variant, volume } = sound.playMusicRequest;
        // Диспатчим экшен для воспроизведения звука
        store.dispatch({ type: 'sound/playSound', payload: { key, variant, volume } });
        
        // Создаем кастомное событие для SoundManager
        window.dispatchEvent(new CustomEvent('playSound', {
          detail: { key, variant, volume }
        }));
        
        // Убираем запрос из состояния
        const { playMusicRequest, ...cleanSoundState } = sound;
        store.dispatch({ type: 'sound/updateSoundState', payload: cleanSoundState });
      } else {
        store.dispatch({ type: 'sound/updateSoundState', payload: sound });
      }
    }
  };
  
  // Запускаем игровой цикл - отправляем текущее состояние в воркер каждую секунду
  setInterval(() => {
    const state = store.getState();
    
    // Если игра не окончена и не находимся на стартовом экране
    if (!state.game.gameOver && !isStartScreenVisible) {
      gameWorker.postMessage({
        type: 'TICK',
        state: state.game,
        soundState: state.sound,
        deltaTime: 1000, // 1 секунда
        windowSize: {
          width: window.innerWidth,
          height: window.innerHeight
        }
      });
    }
  }, 1000);
  
  return next => (action: any) => {
    // Отслеживаем изменения стартового экрана
    if (action.type === 'game/resetGame') {
      isStartScreenVisible = false;
    }
    
    // Если состояние игры изменилось, отправляем его в воркер
    if (action.type && action.type.startsWith('game/') && action.type !== 'game/updateGameState') {
      // Даем выполниться действию в редьюсере
      const result = next(action);
      
      // Получаем обновленное состояние
      const state = store.getState();
      
      // Отправляем в воркер уведомление об изменении состояния
      gameWorker.postMessage({
        type: 'STATE_UPDATED',
        state: state.game,
        soundState: state.sound
      });
      
      return result;
    }
    
    // Для остальных действий просто передаем дальше
    return next(action);
  };
}; 