import React, { useState } from 'react';
import styles from './index.module.scss';
import { useAppSelector } from '../../app/hooks';
import { selectResources, selectTotalAutoIncome, selectManualClickPower, selectAutoClickPower, selectStage } from '../../app/gameSlice';
import CountUp from '../CountUp';
import classNames from 'classnames';

interface TooltipData {
  isVisible: boolean;
  position: { x: number; y: number };
}

const MainResources: React.FC = () => {
  const resources = useAppSelector(selectResources);
  const clickPower = useAppSelector(selectManualClickPower);
  const autoClickPower = useAppSelector(selectAutoClickPower);
  const totalAutoIncome = useAppSelector(selectTotalAutoIncome);
  const stage = useAppSelector(selectStage);
  const [tooltip, setTooltip] = useState<TooltipData>({ 
    isVisible: false,
    position: { x: 0, y: 0 } 
  });

  const handleMouseEnter = (e: React.MouseEvent) => {
    const rect = e.currentTarget.getBoundingClientRect();
    setTooltip({
      isVisible: true,
      position: { 
        x: rect.left, 
        y: rect.bottom + 5 
      }
    });
  };

  const handleMouseLeave = () => {
    setTooltip({ ...tooltip, isVisible: false });
  };

  const getCurrentCPS = () => {
    return (autoClickPower + totalAutoIncome).toFixed(1);
  };

  return (
    <>
      <div 
        className={classNames(styles.mainResources, {
          [styles.stageTwo]: stage === 2
        })}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
      >
        <div className={styles.icon}>💰</div>
        <div className={styles.resourcesContainer}>
          <CountUp value={resources} suffix="₿" duration={950} showColors className={styles.value} />
          <div className={styles.cpsDisplay}>
            {getCurrentCPS()}₿/сек
          </div>
        </div>
      </div>
      
      {tooltip.isVisible && (
        <div 
          className={styles.tooltip} 
          style={{ 
            left: `${tooltip.position.x}px`, 
            top: `${tooltip.position.y}px` 
          }}
        >
          Кликай на страну: +{Math.round(clickPower)}₿ за клик. Общий CPS: {getCurrentCPS()}₿/сек.
        </div>
      )}
    </>
  );
};

export default MainResources; 