import React, { useState, useEffect } from 'react';
import { useAppDispatch } from '../app/hooks';
import { resolveEvent } from '../app/gameSlice';
import styles from './GameEvent.module.scss';
import { GameEvent as GameEventType } from '../types';
import { showCoinEffectThunk } from '../app/visualEffectsSlice';

interface GameEventProps {
  event: GameEventType;
}

// Предустановленные позиции для событий (базовые координаты, масштабируются под размер карты)
const PRESET_POSITIONS = [
  { x: 200, y: 120 },
  { x: 300, y: 160 },
  { x: 150, y: 200 },
  { x: 250, y: 240 },
  { x: 180, y: 180 },
  { x: 320, y: 140 },
];

export const GameEvent: React.FC<GameEventProps> = ({ event }) => {
  const dispatch = useAppDispatch();
  const [mapBounds, setMapBounds] = useState<DOMRect | null>(null);

  // Функция для получения границ игровой области (карты)
  const updateMapBounds = () => {
    // Ищем контейнер карты по классу
    const mapContainer = document.querySelector('[class*="mapContainer"]') as HTMLElement;
    if (mapContainer) {
      const bounds = mapContainer.getBoundingClientRect();
      setMapBounds(bounds);
    }
  };

  // Отслеживание изменения размера окна и обновление границ карты
  useEffect(() => {
    // Обновляем границы при монтировании
    updateMapBounds();
    
    const handleResize = () => {
      updateMapBounds();
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Обновляем границы карты при любых изменениях лейаута
  useEffect(() => {
    const updateBoundsWithDelay = () => {
      // Небольшая задержка для завершения CSS transitions
      setTimeout(updateMapBounds, 100);
    };

    // Наблюдаем за изменениями в DOM
    const observer = new MutationObserver(updateBoundsWithDelay);
    const targetNode = document.body;
    
    if (targetNode) {
      observer.observe(targetNode, { 
        childList: true, 
        subtree: true, 
        attributes: true,
        attributeFilter: ['class', 'style']
      });
    }

    return () => observer.disconnect();
  }, []);

  // Обработчик клика по событию
  const handleClick = (e: React.MouseEvent) => {
    dispatch(resolveEvent(event.id));
    dispatch(showCoinEffectThunk({
      position: {
        x: e.clientX,
        y: e.clientY
      },
      value: event.values || 0
    }));
  };
  
  // Определяем координаты для отображения события в пределах карты
  const getPositionStyle = () => {
    // Если границы карты еще не определены, используем fallback
    if (!mapBounds) {
      return {
        left: '50%',
        top: '50%',
        transform: 'translate(-50%, -50%)'
      };
    }
    
    const margin = 20; // отступ от краев карты
    const mapWidth = mapBounds.width;
    const mapHeight = mapBounds.height;
    const mapLeft = mapBounds.left;
    const mapTop = mapBounds.top;
    
    if (Array.isArray(event.position)) {
      // Конвертируем координаты события в координаты относительно карты
      // Предполагаем, что event.position содержит относительные координаты в пределах карты
      const relativeX = Math.max(margin, Math.min(mapWidth - margin, event.position[0]));
      const relativeY = Math.max(margin, Math.min(mapHeight - margin, event.position[1]));
      
      // Преобразуем в абсолютные координаты viewport
      const absoluteX = mapLeft + relativeX;
      const absoluteY = mapTop + relativeY;
      
      return {
        left: `${absoluteX}px`,
        top: `${absoluteY}px`
      };
    }
    
    // Если позиция не определена или равна "random", используем предустановленные позиции
    // адаптированные под размеры карты
    let targetX: number, targetY: number;
    
    if (PRESET_POSITIONS.length > 0) {
      // Выбираем предустановленную позицию на основе ID события для консистентности
      const index = event.id.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0) % PRESET_POSITIONS.length;
      const preset = PRESET_POSITIONS[index];
      
      // Масштабируем предустановленную позицию под размеры карты
      const scaleX = (mapWidth - 2 * margin) / 400; // предполагаем базовую ширину 400px
      const scaleY = (mapHeight - 2 * margin) / 300; // предполагаем базовую высоту 300px
      
      const scaledX = preset.x * scaleX;
      const scaledY = preset.y * scaleY;
      
      // Убеждаемся, что координаты в пределах карты
      targetX = Math.max(margin, Math.min(mapWidth - margin, scaledX));
      targetY = Math.max(margin, Math.min(mapHeight - margin, scaledY));
    } else {
      // Fallback: генерируем случайную позицию в пределах карты
      targetX = margin + Math.random() * (mapWidth - 2 * margin);
      targetY = margin + Math.random() * (mapHeight - 2 * margin);
    }
    
    // Преобразуем в абсолютные координаты viewport
    const absoluteX = mapLeft + targetX;
    const absoluteY = mapTop + targetY;
    
    return {
      left: `${absoluteX}px`,
      top: `${absoluteY}px`
    };
  };
  
  return (
    <div 
      className={styles.gameEvent} 
      style={getPositionStyle()}
      onClick={handleClick}
    >
      <div className={styles.icon}>{event.icon}</div>
      <div className={styles.tooltip}>{event.message}</div>
    </div>
  );
}; 