import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import styles from './dyson-sphere.module.scss';
import { RootState } from '../../app/store';
import { setSphereMultiplier, selectMultipliers, selectResources, updateResources } from '../../app/gameSlice';
import { MANUAL, COMMON, SCIENCE, FAITH, ECONOMY } from '../../app/constants';

type LaserLevel = 1 | 2 | 3 | 4 | 5 | 6;

interface FallingLaser {
  id: number;
  x: number; // позиция на земле
  y: number;
  level: LaserLevel;
  sphereType: string; // какая сфера (для основных лазеров)
  isMainLaser: boolean; // основной лазер (наука/вера/экономика) или дополнительный
  timestamp: number;
  // Параметры линии лазера
  length: number; // длина линии
  angle: number; // угол наклона в градусах
  startX: number; // начальная точка X (орбита)
  startY: number; // начальная точка Y (орбита)
}

interface Satellite {
  id: number;
  x: number;
  y: number;
  angle: number;
  isLaunching: boolean;
  timestamp: number;
}

interface DysonMultipliers {
  [MANUAL]: number;
  [COMMON]: number;
  [SCIENCE]: number;
  [FAITH]: number;
  [ECONOMY]: number;
}

const RESET_COST = 1000000; // Миллион ресурсов для сброса
const MULTIPLIER_SPHERES = [MANUAL, COMMON, SCIENCE, FAITH, ECONOMY];
const MAX_SATELLITES = 12; // Максимальное количество спутников
const MAIN_SPHERES = [SCIENCE, FAITH, ECONOMY]; // Основные сферы для случайного усиления

export const DysonSphere = () => {
  const dispatch = useDispatch();
  const currentMultipliers = useSelector(selectMultipliers);
  const resources = useSelector(selectResources);
  const [connectionsUsed, setConnectionsUsed] = useState(0);
  const [canConnect, setCanConnect] = useState(true);
  const [gameMultipliers, setGameMultipliers] = useState<DysonMultipliers>({
    [MANUAL]: 1.0,
    [COMMON]: 1.0,
    [SCIENCE]: 1.0,
    [FAITH]: 1.0,
    [ECONOMY]: 1.0
  });
  
  const [fallingLasers, setFallingLasers] = useState<FallingLaser[]>([]);
  const [satellites, setSatellites] = useState<Satellite[]>([]);
  const [fifthConnectionBonuses, setFifthConnectionBonuses] = useState<string[]>([]); // История выборов для 5-х соединений
  const [isResetting, setIsResetting] = useState(false); // Флаг сброса
  
  const previousGameMultipliersRef = useRef<DysonMultipliers>({
    [MANUAL]: 1.0,
    [COMMON]: 1.0,
    [SCIENCE]: 1.0,
    [FAITH]: 1.0,
    [ECONOMY]: 1.0
  });
  
  const laserIdRef = useRef(0);
  const satelliteIdRef = useRef(0);
  const satelliteTimerRef = useRef<NodeJS.Timeout | null>(null);
  const orbitRef = useRef<HTMLDivElement>(null);
  const earthRef = useRef<HTMLDivElement>(null);
  const gameAreaRef = useRef<HTMLDivElement>(null);

  // Получение максимального количества соединений по уровню
  const getMaxConnections = useCallback(() => {
    return 15; // Фиксированный лимит
  }, []);



  // Получение уровня лазера по множителю
  const getLaserLevelByMultiplier = useCallback((multiplier: number): LaserLevel => {
    if (multiplier >= 3.8) return 5; // 380%
    if (multiplier >= 2.9) return 4; // 290%
    if (multiplier >= 2.0) return 3; // 200%
    if (multiplier >= 1.5) return 2; // 150%
    return 1; // базовый уровень
  }, []);

  // Создание линии между точками
  const createLine = useCallback((startPoint: { x: number; y: number }, endPoint: { x: number; y: number }) => {
    // Расчёт параметров линии
    const dx = endPoint.x - startPoint.x;
    const dy = endPoint.y - startPoint.y;
    const length = Math.sqrt(dx * dx + dy * dy);
    const angle = Math.atan2(dy, dx) * 180 / Math.PI;
    
    return { length, angle };
  }, []);

  // Создание нового лазера
  const createLaser = useCallback((isMainLaser: boolean, sphereType?: string) => {
    if (!orbitRef.current || !earthRef.current || !gameAreaRef.current) return;

    const level = isMainLaser && sphereType ? 
      getLaserLevelByMultiplier(gameMultipliers[sphereType as keyof DysonMultipliers]) : 1;

    // Получаем реальные размеры и позиции элементов
    const gameAreaRect = gameAreaRef.current.getBoundingClientRect();
    const orbitRect = orbitRef.current.getBoundingClientRect();
    const earthRect = earthRef.current.getBoundingClientRect();
    
    // Правая точка по середине орбиты (ближайшая к земле)
    const orbitStartX = orbitRect.right + 60 - gameAreaRect.left;
    const orbitStartY = orbitRect.top + orbitRect.height / 2 - gameAreaRect.top;
    
    // Случайная точка на земле
    const earthRandomX = Math.random() * (earthRect.width - 50);
    const earthRandomY = Math.random() * (earthRect.height - 50);
    const earthTargetX = earthRect.left + earthRandomX - gameAreaRect.left + 15;
    const earthTargetY = earthRect.top + earthRandomY - gameAreaRect.top + 15;
    
    // Расчет параметров линии от орбиты до точки на Земле
    const lineParams = createLine(
      { x: orbitStartX, y: orbitStartY },
      { x: earthTargetX, y: earthTargetY }
    );
    
    const newLaser: FallingLaser = {
      id: laserIdRef.current++,
      x: earthTargetX,
      y: earthTargetY,
      level,
      sphereType: sphereType || 'common',
      isMainLaser,
      timestamp: Date.now(),
      length: lineParams.length,
      angle: lineParams.angle,
      startX: orbitStartX,
      startY: orbitStartY
    };
    
    setFallingLasers(prev => [...prev, newLaser]);
  }, [getLaserLevelByMultiplier, gameMultipliers, createLine]);



  // Ручное создание соединения
  const handleConnect = useCallback(() => {
    if (!canConnect || connectionsUsed >= getMaxConnections()) return;
    
    const newConnectionsUsed = connectionsUsed + 1;
    setConnectionsUsed(newConnectionsUsed);
    
    // Логика создания лазеров
    if (newConnectionsUsed <= 3) {
      // Первые 3 соединения создают основные лазеры
      const sphereType = MAIN_SPHERES[newConnectionsUsed - 1];
      createLaser(true, sphereType);
    } else if (newConnectionsUsed % 5 !== 0) {
      // Каждое не-5-е соединение создает дополнительный лазер
      createLaser(false);
    }
    
    // Если это 5-е соединение, сохраняем случайный выбор основной сферы
    if (newConnectionsUsed % 5 === 0) {
      // TODO: Сделать защиту от неудачи
      const randomSphere = MAIN_SPHERES[Math.floor(Math.random() * MAIN_SPHERES.length)];
      setFifthConnectionBonuses(prev => [...prev, randomSphere]);
    }
    
    // Кулдаун 1 секунда
    setCanConnect(false);
    setTimeout(() => setCanConnect(true), 300);
  }, [canConnect, connectionsUsed, getMaxConnections, createLaser]);

  // Сброс игры с тратой ресурсов
  const handleReset = useCallback(() => {
    console.log(resources, RESET_COST);
    if (resources < RESET_COST && process.env.NODE_ENV !== 'development') return;
    console.log('reset');
    
    // Отнимаем предыдущие множители из основной игры
    MULTIPLIER_SPHERES.forEach(sphere => {
      const currentValue = currentMultipliers[sphere] || 1.0;
      const previousValue = previousGameMultipliersRef.current[sphere as keyof DysonMultipliers];
      
      const newReduxValue = currentValue - (previousValue - 1.0);
      
      dispatch(setSphereMultiplier({ 
        sphere, 
        multiplier: Math.max(1.0, newReduxValue) 
      }));
    });
    
    // Тратим ресурсы (только в продакшне)
    if (process.env.NODE_ENV !== 'development') {
      dispatch(updateResources({
        resources: { [COMMON]: -RESET_COST }
      }));
    }
    
    // Устанавливаем флаг сброса
    setIsResetting(true);
    
    // Сбрасываем все состояние одновременно
    const resetState = () => {
      setConnectionsUsed(0);
      setFallingLasers([]);
      setFifthConnectionBonuses([]);
      setGameMultipliers({
        [MANUAL]: 1.0,
        [COMMON]: 1.0,
        [SCIENCE]: 1.0,
        [FAITH]: 1.0,
        [ECONOMY]: 1.0
      });
      previousGameMultipliersRef.current = {
        [MANUAL]: 1.0,
        [COMMON]: 1.0,
        [SCIENCE]: 1.0,
        [FAITH]: 1.0,
        [ECONOMY]: 1.0
      };
    };
    
    // Выполняем сброс синхронно
    resetState();
    
    // Снимаем флаг сброса после завершения
    setTimeout(() => setIsResetting(false), 0);
  }, [resources, currentMultipliers, dispatch]);

  // Запуск спутника
  const launchSatellite = useCallback(() => {
    const newSatellite: Satellite = {
      id: satelliteIdRef.current++,
      x: 300, // Стартовая позиция с Земли (центр)
      y: 50,
      angle: 0,
      isLaunching: true,
      timestamp: Date.now()
    };
    
    setSatellites(prev => {
      let updatedSatellites = [...prev];
      
      // Если достигнут максимум, удаляем самый старый спутник
      if (updatedSatellites.length >= MAX_SATELLITES) {
        // Находим самый старый спутник (с наименьшим timestamp)
        const oldestSatellite = updatedSatellites.reduce((oldest, current) => 
          current.timestamp < oldest.timestamp ? current : oldest
        );
        
        // Удаляем самый старый спутник
        updatedSatellites = updatedSatellites.filter(sat => sat.id !== oldestSatellite.id);
      }
      
      // Добавляем новый спутник
      return [...updatedSatellites, newSatellite];
    });
    
    // Анимация полета к орбите (2 секунды)
    const moveToOrbit = () => {
      setSatellites(prev => prev.map(sat => 
        sat.id === newSatellite.id 
          ? { ...sat, x: 30, y: 75, isLaunching: false }
          : sat
      ));
    };
    
    setTimeout(moveToOrbit, 2000);
  }, []);

  // Движение спутников по орбите
  useEffect(() => {
    const moveInterval = setInterval(() => {
      setSatellites(prev => prev.map(satellite => {
        if (satellite.isLaunching) return satellite;
        
        // Движение по окружности слева от экрана
        const newAngle = (satellite.angle + 0.02) % (Math.PI * 2);
        const centerX = -10; // Центр окружности за левым краем
        const centerY = 40;
        const radius = 150;
        
        return {
          ...satellite,
          angle: newAngle,
          x: centerX + Math.cos(newAngle) * radius,
          y: centerY + Math.sin(newAngle) * radius
        };
      }));
    }, 50);
    
    return () => clearInterval(moveInterval);
  }, []);

  // Таймер спутников
  useEffect(() => {
    // Спутники каждые 10 секунд
    satelliteTimerRef.current = setInterval(launchSatellite, 10000);
    
    return () => {
      if (satelliteTimerRef.current) clearInterval(satelliteTimerRef.current);
    };
  }, [launchSatellite]);

  // Обновление множителей при изменении соединений
  useEffect(() => {
    // Пропускаем пересчет во время сброса
    if (isResetting) return;
    
    const newMultipliers: DysonMultipliers = {
      [MANUAL]: 1.0,
      [COMMON]: 1.0,
      [SCIENCE]: 1.0,
      [FAITH]: 1.0,
      [ECONOMY]: 1.0
    };
    
    // Каждое соединение добавляет 10% ко всем множителям
    const baseBonus = connectionsUsed * 0.1;
    
    // Все сферы получают базовый бонус 10% за каждое соединение
    MULTIPLIER_SPHERES.forEach(sphere => {
      newMultipliers[sphere as keyof DysonMultipliers] = 1.0 + baseBonus;
    });
    
    // Применяем сохраненные бонусы от 5-х соединений
    fifthConnectionBonuses.forEach(bonusSphere => {
      newMultipliers[bonusSphere as keyof DysonMultipliers] += 0.5;
    });
    
    setGameMultipliers(newMultipliers);
    
    // Диспатчим изменения в Redux
    MULTIPLIER_SPHERES.forEach(sphere => {
      const currentValue = currentMultipliers[sphere] || 1.0;
      const previousValue = previousGameMultipliersRef.current[sphere as keyof DysonMultipliers];
      const gameValue = newMultipliers[sphere as keyof DysonMultipliers];
      
      // Отнимаем предыдущий вклад этой игры и добавляем новый
      const newReduxValue = currentValue - (previousValue - 1.0) + (gameValue - 1.0);
      
      dispatch(setSphereMultiplier({ 
        sphere, 
        multiplier: Math.max(1.0, newReduxValue) 
      }));
    });
    
    previousGameMultipliersRef.current = newMultipliers;
  }, [connectionsUsed, fifthConnectionBonuses, currentMultipliers, dispatch, isResetting]);

  // Обновление уровней основных лазеров при изменении множителей
  useEffect(() => {
    // Пропускаем обновление во время сброса
    if (isResetting) return;
    
    setFallingLasers(prev => prev.map(laser => {
      if (laser.isMainLaser && MAIN_SPHERES.includes(laser.sphereType as any)) {
        const newLevel = getLaserLevelByMultiplier(gameMultipliers[laser.sphereType as keyof DysonMultipliers]);
        return { ...laser, level: newLevel };
      }
      return laser;
    }));
  }, [gameMultipliers, getLaserLevelByMultiplier, isResetting]);

  const getSphereDisplayName = (sphere: string) => {
    switch (sphere) {
      case MANUAL: return 'Ручной';
      case COMMON: return 'Общий';
      case SCIENCE: return 'Наука';
      case FAITH: return 'Вера';
      case ECONOMY: return 'Экономика';
      default: return sphere;
    }
  };

  return (
    <div className={styles.container}>
      <div className={styles.header}>
        <h3 className={styles.title}>Сфера Дайсона</h3>
        <div className={styles.stats}>
          <span>Соединений: {connectionsUsed}/{getMaxConnections()}</span>
        </div>
      </div>

      <div className={styles.gameArea} ref={gameAreaRef}>
        {/* Сфера Дайсона слева */}
        <div className={styles.dysonSphere}>
          <div className={styles.sphereOrbit} ref={orbitRef}>
            {satellites.map(satellite => (
              <div
                key={satellite.id}
                className={`${styles.satellite} ${satellite.isLaunching ? styles.launching : ''}`}
                style={{
                  left: `${satellite.x}%`,
                  top: `${satellite.y}%`
                }}
              >
                🛰️
              </div>
            ))}
          </div>
        </div>

        {/* Планета Земля по центру */}
        <div className={styles.earthContainer}>
          <div className={styles.earth} ref={earthRef}>
          </div>
        </div>

        {/* Лазерные линии на уровне игрового поля */}
        {fallingLasers.map(laser => (
          <div
            key={laser.id}
            className={`${styles.laserLine} ${styles[`laserLevel${laser.level+1}`]} ${
              laser.isMainLaser ? styles.mainLaser : styles.additionalLaser
            }`}
            style={{
              height: `${laser.length}px`,
              left: `${laser.startX}px`,
              top: `${laser.startY}px`,
              transformOrigin: '0 0',
              '--angle': `${laser.angle - 90}deg`
            } as React.CSSProperties}
            data-sphere={laser.sphereType}
          />
        ))}

        {/* Панель управления */}
        <div className={styles.multiplierStats}>
            <h4>Множители:</h4>
            {MULTIPLIER_SPHERES.filter(sphere => sphere !== MANUAL && sphere !== COMMON).map(sphere => (
              <div key={sphere} className={styles.multiplierStat}>
                <span>{getSphereDisplayName(sphere)}: </span>
                <span className={MAIN_SPHERES.includes(sphere as any) ? styles.mainSphere : ''}>
                  x{gameMultipliers[sphere as keyof DysonMultipliers].toFixed(2)}
                </span>
              </div>
            ))}
          </div>
        <div className={styles.controls}>
          <button 
            className={styles.connectButton}
            onClick={handleConnect}
            disabled={!canConnect || connectionsUsed >= getMaxConnections()}
          >
            {connectionsUsed >= getMaxConnections() ? 'Лимит достигнут' : 
             !canConnect ? 'Кулдаун...' : 'Соединить'}
          </button>
          
          <button 
            className={styles.resetButton}
            onClick={handleReset}
            disabled={resources < RESET_COST && process.env.NODE_ENV !== 'development'}
          >
            Сброс ({RESET_COST.toLocaleString()} ресурсов)
          </button>
        </div>
      </div>
    </div>
  );
}; 