import React, { useEffect, useState, useRef } from 'react';
import styles from './index.module.scss';

interface CountUpProps {
  value: number;
  duration?: number; // длительность анимации в мс
  decimals?: number; // количество знаков после запятой
  prefix?: string; // префикс перед числом (например "$")
  suffix?: string; // суффикс после числа (например "₿")
  className?: string;
  showColors?: boolean; // показывать ли цветом рост/падение значения
}

// Функция для форматирования больших чисел
const formatLargeNumber = (num: number): string => {
  if (num < 10000) {
    // Показываем полные числа до 10к с разделителями тысяч
    return Math.floor(num).toLocaleString('ru-RU');
  }
  
  const units = [
    { value: 1e33, suffix: 'D' },   // дециллион
    { value: 1e30, suffix: 'N' },   // нониллион  
    { value: 1e27, suffix: 'Oc' },  // октиллион
    { value: 1e24, suffix: 'Sp' },  // септиллион
    { value: 1e21, suffix: 'Sx' },  // секстиллион
    { value: 1e18, suffix: 'Qi' },  // квинтиллион
    { value: 1e15, suffix: 'Q' },   // квадриллион
    { value: 1e12, suffix: 'T' },   // триллион
    { value: 1e9, suffix: 'B' },    // миллиард
    { value: 1e6, suffix: 'М' },    // миллион
    { value: 1e3, suffix: 'К' },    // тысяча (10к+)
  ];
  
  for (const unit of units) {
    if (num >= unit.value) {
      const formattedValue = (num / unit.value).toFixed(2);
      return `${formattedValue}${unit.suffix}`;
    }
  }
  
  return Math.floor(num).toString(); // fallback для целых чисел
};

const CountUp: React.FC<CountUpProps> = ({
  value,
  duration = 500,
  decimals = 2, // теперь по умолчанию 2 знака после запятой
  prefix = '',
  suffix = '',
  className = '',
  showColors = false,
}) => {
  const [displayValue, setDisplayValue] = useState(value);
  const previousValue = useRef(value);
  const animationRef = useRef<number | undefined>(undefined);
  const startTimeRef = useRef<number | undefined>(undefined);
  const isIncreasing = value > previousValue.current;

  useEffect(() => {
    // Если значение не изменилось, не запускаем анимацию
    if (previousValue.current === value) return;

    // Сохраняем начальное значение
    const startValue = previousValue.current;
    
    // Обновляем предыдущее значение
    previousValue.current = value;
    
    // Отмена предыдущей анимации, если она запущена
    if (animationRef.current) {
      cancelAnimationFrame(animationRef.current);
    }

    // Функция анимации
    const animateValue = (timestamp: number) => {
      if (!startTimeRef.current) startTimeRef.current = timestamp;
      
      const elapsed = timestamp - startTimeRef.current;
      
      // Коэффициент прогресса (от 0 до 1)
      const progress = Math.min(elapsed / duration, 1);
      
      // Рассчитываем текущее значение для отображения
      const currentValue = startValue + (value - startValue) * progress;
      
      // Обновляем отображаемое значение
      setDisplayValue(currentValue);
      
      // Если анимация не завершена, продолжаем
      if (progress < 1) {
        animationRef.current = requestAnimationFrame(animateValue);
      } else {
        // Сбрасываем ссылки после завершения
        startTimeRef.current = undefined;
        animationRef.current = undefined;
      }
    };
    
    // Запускаем анимацию
    animationRef.current = requestAnimationFrame(animateValue);
    
    // Очистка при размонтировании
    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, [value, duration]);

  // Форматируем число с сокращениями для больших значений
  const formattedValue = formatLargeNumber(displayValue);
  
  // Определяем классы стилей на основе параметров и изменения значения
  const colorClass = showColors && value !== previousValue.current 
    ? isIncreasing ? styles.positive : styles.negative 
    : '';
  
  return (
    <span className={`${styles.countUp} ${colorClass} ${className}`}>
      {prefix}{formattedValue}{suffix}
    </span>
  );
};

export default CountUp; 